CREATE TABLE CORE.T_DIM_PRODUCT (
   PROD_SID                            NUMERIC         NOT NULL COMMENT 'The unique identifier (surrogate key) for the product',
   DWH_VALID_FROM_TMSP                 TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record became valid.',
   DWH_VALID_TO_TMSP                   TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was no longer valid.',
   DWH_VALID_FG                        BOOLEAN         NOT NULL COMMENT 'An indicator showing the current record in history.',
   PROD_NR                             VARCHAR(20)     NOT NULL COMMENT 'The number for internal onlineshop product, which is country independent',
   PROD_NAME                           VARCHAR(100)    COMMENT 'The centeral name defined for a product by German onlineshop',
   PROD_DESCR                          VARCHAR(250)    COMMENT 'The product information in a free text form',
   IAN_NR                              VARCHAR(20)     COMMENT 'Lidl Internal international product number (international article number)',
   PROD_HIST_NR                        VARCHAR(20)     COMMENT 'Old product number. This number was used as product number in the past.',
   PROD_ASSORTMENT_CLASS_CD            VARCHAR(5)      COMMENT 'The code for the indicating if product is a part of special offer or normal or special assortiment',
   PROD_PACKING_TYPE_CD                VARCHAR(20)     COMMENT 'Code that defines the general type of packaging for the article (i.e. carton, bag)',
   PROD_FOOD_CLASS_CD                  VARCHAR(5)      COMMENT 'The code for the indicating if product is a food or non food',
   BRAND_SID                           NUMERIC         COMMENT 'The unique identifier (surrogate key) for brand',
   BRAND_CLASS_CD                      VARCHAR(5)      COMMENT 'The code for the indicating if product is classified as a Lidl own brand or not',
   PROD_STORAGE_COND_CD                VARCHAR(5)      COMMENT 'The code for the indicating if product is a food or non food',
   PROD_DANG_GOOD_CLASS_CD             VARCHAR(5)      COMMENT 'The code for the indicating if product is a dangerous good  ( if is  a dangerous good and if additional papers are requried).',
   PROD_GROUP_CD                       VARCHAR(20)     COMMENT 'Code of warengruppe - one of the LD classification for the products (DMM165-013, DMM165-014 , etc)',
   PROD_SUBGROUP_CD                    VARCHAR(5)      COMMENT 'The product subgroup code describes the category a product is part of. Such as "baby clothes" or "Workshop - Machines" etc.',
   PROD_FAMILY_CD                      VARCHAR(20)     COMMENT 'The product Family Code represents the lower level of granularity of the Product Categories (sub_prod_group_cd).',
   IS_WINE_SPIRITS_FG                  BOOLEAN         COMMENT 'Flag to identify if the values are belonging to the wine/spirits product gs1 category.',
   IMPORT_NR                           VARCHAR(20)     COMMENT 'Commodity Code/Import Code Number for Foreign Trade',
   SEASON_NR                           VARCHAR(20)     COMMENT 'Unique season ID (Primary Key) in the source system',
   PROD_MATERIAL_TYPE_CD               VARCHAR(5)      COMMENT 'The code for the indicating the material type code for a product ( a regular one , a digital one , etc)',
   PROD_PROMO_CLASS_CD                 VARCHAR(5)      COMMENT 'The code for the indicating if product  is a part of a promotion or main assortment.',
   PROD_PURCH_ORG_TYPE_CD              VARCHAR(5)      COMMENT 'The code for the country / Lidl organization which is responsible for the purchasing (negotiation).',
   SHOP_CAT_SID                        NUMERIC         COMMENT 'Original shop category code',
   SHOP_CAT_NAME                       VARCHAR(250)    COMMENT 'The name by which the shop category is known',
   SHOP_CAT_LVL4_SID                   NUMERIC         COMMENT 'The unique identifier (surrogate key) for shop category level 4',
   SHOP_CAT_LVL4_NAME                  VARCHAR(100)    COMMENT 'The name by which the shop category level 4 for global ( German ) product hierarchy is known.',
   SHOP_CAT_LVL3_SID                   NUMERIC(38,0)   COMMENT 'The unique identifier (surrogate key) for shop category level 3 for global ( German ) product hierarchy',
   SHOP_CAT_LVL3_NAME                  VARCHAR(100)    COMMENT 'The name by which the shop category level 3 for global ( German ) product hierarchy is known.',
   SHOP_CAT_LVL2_SID                   NUMERIC(38,0)   COMMENT 'The unique identifier (surrogate key) for shop category level 2 for global ( German ) product hierarchy',
   SHOP_CAT_LVL2_NAME                  VARCHAR(100)    COMMENT 'The name by which the shop category level 2 is known for global ( German ) product hierarchy',
   SHOP_CAT_LVL1_SID                   NUMERIC(38,0)   COMMENT 'The unique identifier (surrogate key) for  shop category level 1 for global ( German ) product hierarchy',
   PROD_BRICK_CD                       VARCHAR(40)     COMMENT 'The Brickcode is a unique standardized code of all categories in the GS1 article categorization system on level 4 and is maintained for every article in SAP. ',
   PROD_GROUP_LDT_CD                   VARCHAR(50)     COMMENT 'The LDT group of products, based on product family or brick code',
   SHOP_CAT_LVL1_NAME                  VARCHAR(100)    COMMENT 'The name by which the shop category level 1 for global ( German ) product hierarchy is known.',
   IS_BUNDLE_HEADER_FG                 BOOLEAN         COMMENT 'Indicates if product represents a bundle header (may not be consistent in order line)',
   BRAND_NR                            VARCHAR(20)     COMMENT 'A unique number of brand from the source system',
   SHOP_CAT_LVL4_CD                    NUMERIC         COMMENT 'The code by which the shop category level 4 is known.',
   SHOP_CAT_LVL3_CD                    NUMERIC         COMMENT 'The code by which the shop category level 3 is known.',
   SHOP_CAT_LVL2_CD                    NUMERIC         COMMENT 'The code by which the shop category level 2 is known.',
   SHOP_CAT_LVL1_CD                    NUMERIC         COMMENT 'The code by which the shop category level 1 is known.',
   PROD_SRC_INSERT_DT                  DATE            COMMENT 'Date when product was inserted in product catalog',
   PROD_MANAGER_CD                     VARCHAR(100)    COMMENT 'A code indentifiyng the product manager. Util we have actual code value we will be using the name of the manager as a code',
   SUBCATEGORY_OF_NEED_CD              VARCHAR(50)     COMMENT 'The code for main subcategory of Need which the product has been automatically assigned.',
   SUBCATEGORY_OF_NEED_NAME            VARCHAR(100)    COMMENT 'The description for subcategory of need product category',
   CATEGORY_OF_NEED_CD                 VARCHAR(50)     COMMENT 'The code for main Category of Need which the product has been automatically assigned.',
   CATEGORY_OF_NEED_NAME               VARCHAR(100)    COMMENT 'The description for category of need product category',
   WORLD_OF_NEED_CD                    VARCHAR(50)     COMMENT 'The code for the main World of Need which the product has been automatically assigned.',
   WORLD_OF_NEED_NAME                  VARCHAR(100)    COMMENT 'The description for world of need product category',
   PROD_CATEGORY_PPE_NAME              VARCHAR(250)    COMMENT 'The name of the PPE category which the product has been automatically assigned (Profilierung / Pflicht / Ergänzung).',
   PROD_ORG_LVL_NAME                   VARCHAR(50)     COMMENT 'The Organisation level of a product corresponds to the Lidl Digital structure which owns - or is responsible for - these articles (product variants) in the organization.',
   DWH_CREATED_TMSP                    TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
   DWH_UPDATED_TMSP                    TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was last updated.',
   DWH_SRC_FILE_NAME                   VARCHAR(255)    NOT NULL COMMENT 'The path and the name of the file(s) from which this record was loaded.',
   SRC_FILE_TMSP                       TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was extracted from the source.',
   SRC_TABLE_NAME                      VARCHAR(100)    COMMENT 'The name of the source table',   
   CONSTRAINT PK_T_DIM_PRODUCT PRIMARY KEY (PROD_SID, DWH_VALID_FROM_TMSP) NOT ENFORCED 
)  COMMENT = 'The product describes goods and services which are offered by the enterprise. In case of a retailer, these are the goods the company trades with. The term product is not limited to the current assortment of goods and services but may also include articles of competitors or articles which are currently not in the assortment';
